from collections import deque

def comps(g, val, conn=4):
 seen=set(); result=[]; dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
 for r in range(len(g)):
  for c in range(len(g[0])):
   if g[r][c]!=val or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for dx,dy in dirs:
     u,v=x+dx,y+dy
     if 0<=u<7 and 0<=v<7 and (u,v) not in seen and g[u][v]==val:
      seen.add((u,v));q.append((u,v))
   result.append(co)
 return sorted(result,key=len,reverse=True)
